export const getGetRecentActivityUrl = (params?: GetRecentActivityParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/stats/recent-activity?${stringifiedParams}` : `/api/stats/recent-activity`
}

/**
 * @summary Get recent trades across all tokens
 */
